def main():
    os.chdir(ROOT)
    args = sys.argv[1:]
    cmd = args[0] if args else 'build'
    # `add` and `drop` used to stamp a draft onto the desk. Every draft is on the
    # desk now, so both stay only so an older caller does not fail, and both do
    # nothing except rebuild.
    if cmd in ('add', 'drop'):
        print('drafts are the desk. Nothing to stamp, rebuilding.')
        build()
    elif cmd == 'sweep':
        sweep()
        build()
    elif cmd == 'status':
        payload, _ = collect()
        q = [i for i in payload['items'] if i['stage'] == 'draft']
        by = {}
        for i in q:
            by[i['channel']] = by.get(i['channel'], 0) + 1
        print(f'{len(q)} draft(s) waiting on a verdict')
        for k, v in sorted(by.items()):
            print(f'  {k:10} {v}')
    elif cmd == 'serve':
        port = PORT
        if '--port' in args:
            port = int(args[args.index('--port') + 1])
        # `--stop` and `--restart` exist because a code edit needs a restart and
        # DESK.cmd cannot give one: it finds the port busy and reuses whatever
        # is there.
        if '--stop' in args:
            stop(port)
            return
        if '--restart' in args and not stop(port):
            # Falling through to serve() here would find the port busy and
            # quietly hand back the very server the restart was meant to
            # replace, which is the silent failure this whole path exists to
            # remove. Stop instead, and say what to do.
            return
        serve(port)
    elif cmd == 'single':
        single(args[1] if len(args) > 1 else os.path.join(ROOT, 'REVIEW-single.html'))
    else:
        build()


if __name__ == '__main__':
    main()
